const DATA = "data";
const IIIF = "https://edition.onb.ac.at/iiif/okopenko/";
const DIARIES = [
  "TB_1949.12.19-1950.01.04.xml","TB_1950.01.05-1950.02.12.xml","TB_1950.02.13-1950.02.28.xml","TB_1950.03.01-1950.03.31.xml","TB_1950.04.01-1950.04.30.xml","TB_1950.05.01-1950.05.31.xml","TB_1950.06.01-1950.06.30.xml","TB_1950.07.01-1950.07.31.xml","TB_1950.08.01-1950.08.31.xml","TB_1950.09.01-1950.09.30.xml","TB_1950.10.01-1950.12.31.xml","TB_1950.11.22-1951.01.27.xml","TB_1951.01.01-1951.11.30.xml","TB_1951.04.13-1951.05.24.xml","TB_1951.12.01-1951.12.31.xml","TB_1952.01.01-1952.02.29.xml","TB_1952.03.01-1952.04.18.xml","TB_1952.04.18-1952.06.27.xml","TB_1952.06.28-1952.08.03.xml","TB_1952.08.04-1952.08.24.xml","TB_1952.08.25-1952.09.14.xml","TB_1952.09.15-1952.11.02.xml","TB_1952.11.03-1952.11.23.xml","TB_1952.11.24-1952.12.22.xml","TB_1952.12.23-1953.02.02.xml","TB_1953.02.03-1953.04.30.xml","TB_1953.05.01-1953.06.15.xml","TB_1953.06.16-1953.12.28.xml","TB_1954.01.14-1954.02.26.xml","TB_1954.03.03-1954.05.15.xml"
];
const REGISTRY_FILES = { person: "Persons.xml", place: "Places.xml", org: "Organisations.xml", work: "Bibliography.xml" };
const state = { diaryIndex: 0, pageIndex: 0, mode: "reading", docs: new Map(), registries: {}, registerType: "person", comments: [], activeComment: null };
const $ = (selector) => document.querySelector(selector);
const escapeHTML = (text = "") => text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
const local = (node) => node?.localName || "";
const all = (root, name) => [...root.getElementsByTagNameNS("*", name)];
const first = (root, name) => all(root, name)[0];
const plain = (node) => (node?.textContent || "").replace(/\s+/g, " ").trim();

async function fetchXML(path) {
  const response = await fetch(`${DATA}/${path}`);
  if (!response.ok) throw new Error(`${path}: ${response.status}`);
  const xml = new DOMParser().parseFromString(await response.text(), "application/xml");
  if (xml.querySelector("parsererror")) throw new Error(`XML konnte nicht gelesen werden: ${path}`);
  return xml;
}

function periodFromFile(file) { return file.slice(3, -4).replaceAll(".", "").replace("-", " – "); }
function diaryTitle(doc) { return plain(first(first(doc, "titleStmt"), "title")) || "Tagebuch"; }
function registryName(type) { return { person: "Person", place: "Ort", org: "Institution", work: "Werk" }[type]; }

async function initialize() {
  try {
    $("#text-content").innerHTML = '<p class="loading">Edition wird vorbereitet …</p>';
    const entries = await Promise.all(Object.entries(REGISTRY_FILES).map(async ([type, file]) => [type, await fetchXML(`Register/${file}`)]));
    state.registries = Object.fromEntries(entries);
    buildDiarySelect();
    await loadDiary(0);
    bindEvents();
    renderRegister();
  } catch (error) {
    $("#text-content").innerHTML = `<p class="empty-state"><b>Die Daten konnten nicht geladen werden.</b><br>${escapeHTML(error.message)}<br><br>Starten Sie die Anwendung über einen lokalen Webserver, nicht direkt als Datei.</p>`;
  }
}

function buildDiarySelect() {
  $("#diary-select").innerHTML = DIARIES.map((file, index) => `<option value="${index}">${periodFromFile(file)}</option>`).join("");
}

async function loadDiary(index) {
  state.diaryIndex = index; state.pageIndex = 0; state.activeComment = null;
  const file = DIARIES[index];
  let doc = state.docs.get(file);
  if (!doc) { doc = await fetchXML(file); state.docs.set(file, doc); }
  state.currentDoc = doc;
  const commentPath = `Stellenkommentar/COM_${file.slice(3)}`;
  try {
    const commentDoc = await fetchXML(commentPath);
    state.comments = all(commentDoc, "note").filter(n => n.getAttribute("type") === "comment").map((n, index) => ({ number: index + 1, text: plain(n), target: n.getAttribute("target") || "" }));
  } catch { state.comments = []; }
  $("#diary-select").value = index;
  $("#reader-period").textContent = periodFromFile(file);
  $("#reader-title").textContent = diaryTitle(doc).replace(" - Digitale Edition", "");
  renderEntries(); renderPages(); renderReader();
}

function pages() { return all(state.currentDoc, "pb"); }
function pageRange() {
  const list = pages(), page = list[state.pageIndex];
  const range = document.createRange();
  range.setStartAfter(page);
  if (list[state.pageIndex + 1]) range.setEndBefore(list[state.pageIndex + 1]);
  else range.selectNodeContents(first(state.currentDoc, "text"));
  return { page, fragment: range.cloneContents() };
}

function renderPages() {
  const list = pages();
  $("#page-select").innerHTML = list.map((p, index) => `<option value="${index}">${p.getAttribute("n") || index + 1}</option>`).join("");
}

function renderEntries() {
  const entries = all(state.currentDoc, "div").filter(d => d.getAttribute("type") === "entry");
  $("#entry-list").innerHTML = entries.length ? entries.map((entry, index) => {
    const date = first(entry, "date"); const pageIndex = precedingPageIndex(entry);
    return `<button class="entry-item" data-page="${pageIndex}"><span>${escapeHTML(plain(first(entry, "dateline")) || `Eintrag ${index + 1}`)}</span><small>${escapeHTML(date?.getAttribute("when-iso") || "undatiert")}</small></button>`;
  }).join("") : '<p class="empty-state">Keine datierten Einträge in diesem Konvolut.</p>';
}

function precedingPageIndex(element) {
  const list = pages();
  let best = 0;
  for (let i = 0; i < list.length; i++) if (list[i].compareDocumentPosition(element) & Node.DOCUMENT_POSITION_FOLLOWING) best = i;
  return best;
}

function renderReader() {
  const { page, fragment } = pageRange();
  const facs = page.getAttribute("facs") || "";
  $("#page-select").value = state.pageIndex;
  $("#previous-page").disabled = state.pageIndex === 0;
  $("#next-page").disabled = state.pageIndex === pages().length - 1;
  const image = $("#facsimile");
  image.src = facs ? `${IIIF}${facs}/full/1000,/0/default.jpg` : "";
  image.onerror = () => { $("#facs-caption").textContent = "Das Digitalisat ist derzeit nicht erreichbar. Die TEI-Referenz bleibt verfügbar."; };
  $("#iiif-link").href = facs ? `${IIIF}${facs}/info.json` : "#";
  $("#facs-caption").textContent = `Blatt ${page.getAttribute("n") || state.pageIndex + 1} · ${facs || "ohne Faksimile-Verweis"}`;
  const root = document.createElement("div"); root.append(fragment);
  const raw = new XMLSerializer().serializeToString(root);
  const content = $("#text-content");
  $("#text-label").textContent = state.mode === "source" ? "TEI-Ausschnitt" : state.mode === "diplomatic" ? "Diplomatische Umschrift" : "Lesefassung";
  content.className = `edition-text ${state.mode}`;
  content.innerHTML = state.mode === "source" ? `<code class="source">${escapeHTML(raw)}</code>` : renderChildren(root, state.mode);
  content.scrollTop = 0;
  $("#commentary").hidden = !state.activeComment;
  if (state.activeComment) showComment(state.activeComment);
  document.querySelectorAll(".entry-item").forEach(item => item.classList.toggle("is-active", Number(item.dataset.page) === state.pageIndex));
}

function renderChildren(node, mode) { return [...node.childNodes].map(child => renderNode(child, mode)).join(""); }
function renderNode(node, mode) {
  if (node.nodeType === Node.TEXT_NODE) return escapeHTML(node.nodeValue);
  if (node.nodeType !== Node.ELEMENT_NODE) return "";
  const tag = local(node), inner = renderChildren(node, mode), attr = name => node.getAttribute(name) || "";
  if (tag === "pb") return "";
  if (tag === "lb") return mode === "diplomatic" ? "<br>" : " ";
  if (tag === "p") return `<p>${inner}</p>`;
  if (tag === "dateline") return `<div class="dateline">${inner}</div>`;
  if (tag === "div") return `<section class="${attr("type") === "entry" ? "entry" : ""}">${inner}</section>`;
  if (tag === "head") return `<h3>${inner}</h3>`;
  if (tag === "hi") return `<span class="hi ${escapeHTML(attr("rend"))}">${inner}</span>`;
  if (tag === "del") return mode === "reading" ? "" : `<del class="deleted">${inner}</del>`;
  if (tag === "add") return `<ins class="addition">${inner}</ins>`;
  if (tag === "subst") return inner;
  if (tag === "choice") {
    const preferred = mode === "reading" ? first(node, "corr") || first(node, "expan") : node;
    return preferred === node ? inner : renderChildren(preferred, mode);
  }
  if (tag === "gap") return `<span class="gap">[${escapeHTML(attr("reason") || "Auslassung")}]</span>`;
  if (tag === "unclear") return `<span class="unclear" title="Unsichere Lesung">${inner}</span>`;
  if (tag === "space") return mode === "diplomatic" ? `<span class="gap">[${attr("quantity") || ""} Leerzeichen]</span>` : " ";
  if (tag === "rs") return `<button class="entity-link" data-ref="${escapeHTML(attr("ref"))}" data-type="${escapeHTML(attr("type"))}">${inner}</button>`;
  if (tag === "anchor") {
    const note = state.comments.find(c => c.target.includes(`#${attr("xml:id")}`));
    return note ? `<button class="comment-marker" data-comment="${note.number}" title="Stellenkommentar ${note.number}">${note.number}</button>` : "";
  }
  if (tag === "floatingText") return `<aside class="floating-text"><span class="eyebrow">Beilage${attr("type") ? ` · ${escapeHTML(attr("type"))}` : ""}</span>${inner}</aside>`;
  if (tag === "figure") return `<aside class="floating-text">${inner}</aside>`;
  if (tag === "figDesc") return `<p><em>[Abbildung: ${inner}]</em></p>`;
  if (["body", "front", "back", "text", "note", "seg", "quote", "abbr", "expan", "corr", "sic", "supplied", "metamark", "date", "name", "persName", "orgName"].includes(tag)) return inner;
  if (tag === "milestone") return `<hr>`;
  return inner;
}

function showComment(number) {
  const comment = state.comments.find(c => c.number === Number(number)); if (!comment) return;
  state.activeComment = comment.number;
  const box = $("#commentary"); box.hidden = false;
  box.innerHTML = `<h3><span class="comment-number">${comment.number.toString().padStart(2, "0")}</span> Stellenkommentar</h3><p>${escapeHTML(comment.text)}</p>`;
  box.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function elementsForType(type) {
  const doc = state.registries[type];
  return type === "person" ? all(doc, "person") : type === "place" ? all(doc, "place") : type === "org" ? all(doc, "org") : all(doc, "biblStruct");
}
function labelForElement(element, type) {
  if (type === "person") return plain(first(element, "reg")) || plain(first(element, "persName"));
  if (type === "place") return plain(first(element, "placeName")) || plain(first(element, "geogName"));
  if (type === "org") return plain(first(element, "orgName"));
  return plain(first(element, "title"));
}
function metadataForElement(element, type) {
  if (type === "person") return [element.getAttribute("role"), plain(first(element, "birth")) && `* ${plain(first(element, "birth"))}`].filter(Boolean).join(" ");
  if (type === "place" || type === "org") return plain(first(element, "address")) || (all(element, "geo").length ? "kartierbar" : "ohne Geodaten");
  return [plain(first(element, "author")), plain(first(element, "date"))].filter(Boolean).join(" · ");
}
function renderRegister() {
  const type = state.registerType, search = $("#register-search").value.toLocaleLowerCase("de");
  const matches = elementsForType(type).filter(item => `${labelForElement(item, type)} ${plain(item)}`.toLocaleLowerCase("de").includes(search)).slice(0, 120);
  $("#register-results").innerHTML = matches.length ? matches.map((item, index) => `<button class="result-item" data-id="${escapeHTML(item.getAttribute("xml:id"))}"><span class="result-index">${String(index + 1).padStart(3, "0")}</span><span><strong>${escapeHTML(labelForElement(item, type))}</strong><small>${escapeHTML(metadataForElement(item, type) || registryName(type))}</small></span></button>`).join("") : '<p class="empty-state">Keine passenden Registereinträge.</p>';
  $("#register-detail").innerHTML = `<p class="detail-placeholder">${matches.length} Einträge${search ? " für diese Suche" : " im Register"}. Wählen Sie einen Eintrag für Details.</p>`;
}
function showRegistryDetail(type, id) {
  const item = elementsForType(type).find(element => element.getAttribute("xml:id") === id); if (!item) return;
  const notes = all(item, "note").map(plain).filter(Boolean);
  const external = first(item, "persName")?.getAttribute("ref") || first(item, "ref")?.getAttribute("target") || "";
  $("#register-detail").innerHTML = `<p class="detail-meta">${escapeHTML(registryName(type))}${item.getAttribute("cert") ? ` · Sicherheit: ${escapeHTML(item.getAttribute("cert"))}` : ""}</p><h2>${escapeHTML(labelForElement(item, type))}</h2><p>${escapeHTML(metadataForElement(item, type))}</p>${notes.length ? `<div class="detail-notes">${notes.map(note => `<p>${escapeHTML(note)}</p>`).join("")}</div>` : ""}${external ? `<a class="detail-link" target="_blank" rel="noreferrer" href="${escapeHTML(external)}">Normdaten / Quelle ↗</a>` : ""}`;
}
function openEntity(ref, type) {
  const id = ref.trim().split(/\s+/)[0].replace(/^#/, "");
  if (!id || !REGISTRY_FILES[type]) return toast("Für diese Nennung ist kein Registereintrag hinterlegt.");
  showSection("register"); state.registerType = type;
  document.querySelectorAll(".register-type").forEach(button => button.classList.toggle("is-active", button.dataset.register === type));
  $("#register-search").value = ""; renderRegister(); showRegistryDetail(type, id);
}
function showInfo() {
  const header = first(state.currentDoc, "teiHeader");
  const title = diaryTitle(state.currentDoc), shelfmark = all(header, "idno").find(i => i.getAttribute("type") === "shelfmark");
  const pid = all(header, "idno").find(i => i.getAttribute("type") === "PID");
  $("#dialog-content").innerHTML = `<p class="eyebrow">Dokumentinformation</p><h2 class="dialog-title">${escapeHTML(title)}</h2><dl class="dialog-grid"><dt>Konvolut</dt><dd>${escapeHTML(periodFromFile(DIARIES[state.diaryIndex]))}</dd><dt>Signatur</dt><dd>${escapeHTML(plain(shelfmark) || "—")}</dd><dt>PID</dt><dd>${escapeHTML(plain(pid) || "—")}</dd><dt>Seiten</dt><dd>${pages().length}</dd><dt>Kommentar</dt><dd>${state.comments.length ? `${state.comments.length} Stellenkommentare` : "kein separater Kommentar"}</dd></dl>`;
  $("#info-dialog").showModal();
}
function showSection(id) {
  document.querySelectorAll(".view").forEach(view => view.classList.toggle("is-visible", view.id === id));
  document.querySelectorAll(".nav-link").forEach(link => link.classList.toggle("is-active", link.dataset.section === id));
  window.scrollTo({ top: 0, behavior: "smooth" });
  $(".main-nav").classList.remove("is-open");
}
let toastTimer;
function toast(message) { const el = $("#toast"); el.textContent = message; el.classList.add("is-visible"); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove("is-visible"), 3200); }
function bindEvents() {
  $("#diary-select").addEventListener("change", event => loadDiary(Number(event.target.value)));
  $("#page-select").addEventListener("change", event => { state.pageIndex = Number(event.target.value); state.activeComment = null; renderReader(); });
  $("#previous-page").addEventListener("click", () => { if (state.pageIndex) { state.pageIndex--; state.activeComment = null; renderReader(); } });
  $("#next-page").addEventListener("click", () => { if (state.pageIndex < pages().length - 1) { state.pageIndex++; state.activeComment = null; renderReader(); } });
  $("#entry-list").addEventListener("click", event => { const button = event.target.closest(".entry-item"); if (button) { state.pageIndex = Number(button.dataset.page); state.activeComment = null; renderReader(); } });
  document.querySelectorAll(".reader-tab").forEach(button => button.addEventListener("click", () => { state.mode = button.dataset.mode; document.querySelectorAll(".reader-tab").forEach(tab => { tab.classList.toggle("is-active", tab === button); tab.setAttribute("aria-selected", tab === button); }); renderReader(); }));
  $("#text-content").addEventListener("click", event => { const comment = event.target.closest("[data-comment]"); const entity = event.target.closest("[data-ref]"); if (comment) showComment(comment.dataset.comment); if (entity) openEntity(entity.dataset.ref, entity.dataset.type); });
  $("#show-document-info").addEventListener("click", showInfo);
  $(".dialog-close").addEventListener("click", () => $("#info-dialog").close());
  document.querySelectorAll(".nav-link").forEach(link => link.addEventListener("click", () => showSection(link.dataset.section)));
  $("#mobile-menu").addEventListener("click", () => $(".main-nav").classList.toggle("is-open"));
  document.querySelectorAll(".register-type").forEach(button => button.addEventListener("click", () => { state.registerType = button.dataset.register; document.querySelectorAll(".register-type").forEach(tab => tab.classList.toggle("is-active", tab === button)); renderRegister(); }));
  $("#register-search").addEventListener("input", renderRegister);
  $("#register-results").addEventListener("click", event => { const result = event.target.closest(".result-item"); if (result) showRegistryDetail(state.registerType, result.dataset.id); });
}
initialize();
# Okopenko · Leseraum

Statische, datengetriebene Präsentationsschicht für die unter `data/` liegende
TEI-Edition. Die Anwendung benötigt keinen Build-Schritt. Sie muss wegen der
XML-Abrufe über einen lokalen Webserver laufen, beispielsweise:

```sh
python3 -m http.server 8000
```

Anschliessend `http://localhost:8000` öffnen.

Die Oberfläche verwendet die TEI-Transkriptionen direkt im Browser, lädt die
vier Register bei Start und leitet aus `pb/@facs` IIIF-Image-API-URLs ab.
