const patch = "*** Begin Patch
*** Update File: /Users/bastian/projects/buw/research/agentic_ed_coding/agentic_ed_coding_lab/app.js
@@
 function renderReader() {
@@
   document.querySelectorAll(".entry-item").forEach(item => item.classList.toggle("is-active", Number(item.dataset.page) === state.pageIndex));
 }
+
+function renderThemes() {
+  $("#theme-list").innerHTML = state.themes.map((theme, index) => `<button class="theme-choice ${index === state.themeIndex ? "is-active" : ""}" role="tab" aria-selected="${index === state.themeIndex}" data-theme="${index}"><small>${escapeHTML(theme.kicker)}</small><strong>${escapeHTML(theme.label)}</strong></button>`).join("");
+  const theme = state.themes[state.themeIndex];
+  if (!theme) return;
+  $("#theme-content").innerHTML = renderThemeChildren(first(theme.doc, "body"));
+}
+
+function renderThemeChildren(node) { return [...node.childNodes].map(renderThemeNode).join(""); }
+function renderThemeNode(node) {
+  if (node.nodeType === Node.TEXT_NODE) return escapeHTML(node.nodeValue);
+  if (node.nodeType !== Node.ELEMENT_NODE) return "";
+  const tag = local(node), inner = renderThemeChildren(node), target = node.getAttribute("target") || "";
+  if (["ref", "quote"].includes(tag) && target.startsWith("range(")) return `<button class="theme-jump" data-target="${escapeHTML(target)}" title="Zur markierten Tagebuchstelle">${inner}</button>`;
+  if (tag === "p") return `<p>${inner}</p>`;
+  if (tag === "head") return `<h2>${inner}</h2>`;
+  if (tag === "div") return `<section>${inner}</section>`;
+  if (tag === "hi") return `<span class="hi ${escapeHTML(node.getAttribute("rend") || "")}">${inner}</span>`;
+  if (tag === "rs") return `<button class="entity-link" data-ref="${escapeHTML(node.getAttribute("ref") || "")}" data-type="${escapeHTML(node.getAttribute("type") || "")}">${inner}</button>`;
+  if (tag === "list") return `<ul>${inner}</ul>`;
+  if (tag === "item") return `<li>${inner}</li>`;
+  return inner;
+}
+
+async function openThemeTarget(target) {
+  const anchor = target.match(/#([^,\s)]+)/)?.[1];
+  if (!anchor) return toast("Für diesen Verweis ist keine lokale Tagebuchstelle ermittelbar.");
+  let targetIndex = -1, targetAnchor;
+  for (let index = 0; index < DIARIES.length; index++) {
+    const file = DIARIES[index]; let doc = state.docs.get(file);
+    if (!doc) { doc = await fetchXML(file); state.docs.set(file, doc); }
+    const found = all(doc, "anchor").find(item => item.getAttribute("xml:id") === anchor);
+    if (found) { targetIndex = index; targetAnchor = found; break; }
+  }
+  if (targetIndex < 0) return toast("Die referenzierte Stelle ist im bereitgestellten Datenbestand nicht enthalten.");
+  await loadDiary(targetIndex);
+  state.pageIndex = precedingPageIndex(targetAnchor);
+  renderReader(); showSection("edition");
+  toast("Zur verknüpften Tagebuchstelle gesprungen.");
+}

 function renderChildren(node, mode) { return [...node.childNodes].map(child => renderNode(child, mode)).join(""); }
*** End Patch";
